-- Egypt governorates, cities, centers and localities. Standard SQL. On MySQL use the utf8mb4 character set.

CREATE TABLE governorates (
  id INTEGER PRIMARY KEY,
  code VARCHAR(255),
  iso_3166_2 VARCHAR(255),
  name_ar VARCHAR(255),
  name_en VARCHAR(255),
  latitude DOUBLE PRECISION,
  longitude DOUBLE PRECISION,
  area_sqkm DOUBLE PRECISION
);

CREATE TABLE cities (
  id INTEGER PRIMARY KEY,
  code VARCHAR(255),
  governorate_id INTEGER,
  governorate_code VARCHAR(255),
  name_ar VARCHAR(255),
  name_en VARCHAR(255),
  is_capital INTEGER,
  center_codes VARCHAR(255),
  name_ar_search VARCHAR(255),
  location_quality VARCHAR(255),
  latitude DOUBLE PRECISION,
  longitude DOUBLE PRECISION,
  FOREIGN KEY (governorate_id) REFERENCES governorates (id)
);

CREATE TABLE centers (
  id INTEGER PRIMARY KEY,
  code VARCHAR(255),
  governorate_id INTEGER,
  governorate_code VARCHAR(255),
  type VARCHAR(255),
  name_ar VARCHAR(255),
  name_en VARCHAR(255),
  label_en VARCHAR(255),
  name_ar_search VARCHAR(255),
  source VARCHAR(255),
  status VARCHAR(255),
  replaces_code VARCHAR(255),
  founded INTEGER,
  location_quality VARCHAR(255),
  latitude DOUBLE PRECISION,
  longitude DOUBLE PRECISION,
  area_sqkm DOUBLE PRECISION,
  FOREIGN KEY (governorate_id) REFERENCES governorates (id)
);

CREATE TABLE localities (
  id INTEGER PRIMARY KEY,
  code VARCHAR(255),
  center_id INTEGER,
  center_code VARCHAR(255),
  governorate_id INTEGER,
  governorate_code VARCHAR(255),
  type VARCHAR(255),
  name_ar VARCHAR(255),
  name_en VARCHAR(255),
  name_en_source VARCHAR(255),
  name_ar_search VARCHAR(255),
  notes_ar VARCHAR(255),
  source VARCHAR(255),
  location_quality VARCHAR(255),
  latitude DOUBLE PRECISION,
  longitude DOUBLE PRECISION,
  area_sqkm DOUBLE PRECISION,
  FOREIGN KEY (center_id) REFERENCES centers (id)
);

CREATE INDEX idx_centers_governorate ON centers (governorate_id);
CREATE INDEX idx_localities_center ON localities (center_id);
CREATE INDEX idx_localities_governorate ON localities (governorate_id);
